import{_ as d,o as e,c as r,a2 as o}from"./chunks/framework.doxMM-x8.js";const A=JSON.parse('{"title":"API 配置","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/reference/config","contentType":"reference","prev":false,"next":false},"headers":[],"relativePath":"reference/config.md","filePath":"reference/config.md"}'),c={name:"reference/config.md"};function a(_,t,T,n,I,E){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="api-配置" tabindex="-1">API 配置 <a class="header-anchor" href="#api-配置" aria-label="Permalink to &quot;API 配置&quot;">​</a></h1><p>Node 配置直接来自运行服务的解析器。使用方法见 <a href="./../guides/server-platform">平台指南</a>。生产秘密不进入文档。</p><h2 id="当前-lab-word-server" tabindex="-1">当前 Lab Word Server <a class="header-anchor" href="#当前-lab-word-server" aria-label="Permalink to &quot;当前 Lab Word Server&quot;">​</a></h2><p>默认值由 <a href="https://github.com/CaiZongyuan/labworld/blob/6f962c1dd133b7cede1e2cc8e70e89c839f6de6b/apps/server/src/config.ts" target="_blank" rel="noreferrer">config.ts</a> 的实际解析器生成。Web 的 <code>WEB_PORT</code> 和 <code>VITE_API_PROXY</code> 由开发入口和 Vite 读取。</p><table tabindex="0"><thead><tr><th>变量</th><th>默认值</th><th>敏感值</th><th>说明</th></tr></thead><tbody><tr><td><code>LAB_WORD_WEB_DIR</code></td><td></td><td>否</td><td>生产同源托管的 Web 构建目录；空值关闭静态托管。</td></tr><tr><td><code>LAB_WORD_HOST</code></td><td>127.0.0.1</td><td>否</td><td>监听主机；兼容回退为 APP_BIND。</td></tr><tr><td><code>SERVER_PORT</code></td><td>3000</td><td>否</td><td>监听端口，整数 1–65535。</td></tr><tr><td><code>APP_ORIGIN</code></td><td><a href="http://127.0.0.1:5173" target="_blank" rel="noreferrer">http://127.0.0.1:5173</a></td><td>否</td><td>可信 Web origin；HTTPS 或回环 HTTP。</td></tr><tr><td><code>SESSION_ABSOLUTE_SECS</code></td><td>604800</td><td>否</td><td>会话绝对有效期秒数，60–2592000。</td></tr><tr><td><code>SESSION_IDLE_SECS</code></td><td>86400</td><td>否</td><td>会话空闲有效期秒数，60 至绝对有效期。</td></tr><tr><td><code>RATE_LIMIT_ENABLED</code></td><td>true</td><td>否</td><td>启用进程内限流，true 或 false。</td></tr><tr><td><code>RATE_LIMIT_WINDOW_SECS</code></td><td>60</td><td>否</td><td>整数 1–3600；额度按 TCP peer，溢出额度不能超过主额度。</td></tr><tr><td><code>RATE_LIMIT_MAX_LOCAL_ENTRIES</code></td><td>4096</td><td>否</td><td>整数 1–100000；额度按 TCP peer，溢出额度不能超过主额度。</td></tr><tr><td><code>RATE_LIMIT_REGISTRATION</code></td><td>20</td><td>否</td><td>整数 1–1000000；额度按 TCP peer，溢出额度不能超过主额度。</td></tr><tr><td><code>RATE_LIMIT_REGISTRATION_FALLBACK</code></td><td>5</td><td>否</td><td>整数 1–1000000；额度按 TCP peer，溢出额度不能超过主额度。</td></tr><tr><td><code>RATE_LIMIT_AUTHENTICATION</code></td><td>60</td><td>否</td><td>整数 1–1000000；额度按 TCP peer，溢出额度不能超过主额度。</td></tr><tr><td><code>RATE_LIMIT_AUTHENTICATION_FALLBACK</code></td><td>20</td><td>否</td><td>整数 1–1000000；额度按 TCP peer，溢出额度不能超过主额度。</td></tr><tr><td><code>RATE_LIMIT_RESOURCE</code></td><td>600</td><td>否</td><td>整数 1–1000000；额度按 TCP peer，溢出额度不能超过主额度。</td></tr><tr><td><code>RATE_LIMIT_RESOURCE_FALLBACK</code></td><td>120</td><td>否</td><td>整数 1–1000000；额度按 TCP peer，溢出额度不能超过主额度。</td></tr><tr><td><code>FILE_MAX_BYTES</code></td><td>20971520</td><td>否</td><td>整数 1–104857600；流式字节上限。</td></tr><tr><td><code>UPLOAD_SESSION_SECS</code></td><td>900</td><td>否</td><td>整数 1–3600；capability 有效期秒数。</td></tr><tr><td><code>DOWNLOAD_URL_SECS</code></td><td>60</td><td>否</td><td>整数 1–300；capability 有效期秒数。</td></tr><tr><td><code>FILE_PUBLIC_ORIGIN</code></td><td><a href="http://127.0.0.1:5173" target="_blank" rel="noreferrer">http://127.0.0.1:5173</a></td><td>否</td><td>字节 URL 的 origin；默认使用可信 Web origin，HTTPS 或回环 HTTP。</td></tr><tr><td><code>LAB_OBSERVATION_RETENTION_SECS</code></td><td>86400</td><td>否</td><td>原始观测保留秒数（1–31536000）；保留当前属性。</td></tr><tr><td><code>LAB_RECORD_RETENTION_SECS</code></td><td>2592000</td><td>否</td><td>结束记录保留秒数（1–31536000）；保留在途 Task。</td></tr><tr><td><code>LAB_WORD_DATA_DIR</code></td><td>data</td><td>否</td><td>拥有的持久数据库、字节与密钥目录；测试回退为 CONTRACT_DATA_DIRECTORY。</td></tr></tbody></table><p><a href="https://github.com/CaiZongyuan/labworld/blob/6f962c1dd133b7cede1e2cc8e70e89c839f6de6b/.env.example" target="_blank" rel="noreferrer">.env.example</a>展示当前 Node 与 Web 配置；普通服务不读取旧数据库、Redis 或对象存储设置。服务与 Web 的启动见 <a href="./../guides/server-foundation">TypeScript 服务基础</a>。</p>',6)])])}const p=d(c,[["render",a]]);export{A as __pageData,p as default};
